[CmdletBinding()]
param([string[]]$Keywords,[string]$KeywordsFile='',[ValidateSet('Html','Csv')][string]$Format='Html',[string]$OutputPath='',[string]$SearchType='',[int]$RowPerPage=30)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$baseUrl='https://www.hscity.go.kr/www/organ/BD_selectOrganList.do'
function New-StaffSearchUrl{param([Parameter(Mandatory)][string]$Keyword);$pairs=[ordered]@{q_deptCode='';q_parntsAt='';q_searchType=$SearchType;q_searchVal=$Keyword;q_rowPerPage=[string]$RowPerPage;q_currPage='1';q_sortName='';q_sortOrder=''};$query=($pairs.GetEnumerator()|ForEach-Object{'{0}={1}'-f([uri]::EscapeDataString($_.Key)),([uri]::EscapeDataString([string]$_.Value))})-join'&';return "$baseUrl`?$query"}
function Resolve-OutputPath{param([Parameter(Mandatory)][string]$Path);if([System.IO.Path]::IsPathRooted($Path)){return[System.IO.Path]::GetFullPath($Path)};return[System.IO.Path]::GetFullPath((Join-Path(Get-Location)$Path))}
$items=@();if($Keywords){$items+=$Keywords};if($KeywordsFile){$resolved=Resolve-Path -LiteralPath $KeywordsFile;$items+=Get-Content -LiteralPath $resolved.Path|Where-Object{$_.Trim()}};$items=@($items|ForEach-Object{[string]$_ -split','}|ForEach-Object{$_.Trim()}|Where-Object{$_}|Select-Object -Unique);if($items.Count-eq 0){throw'Provide at least one keyword with -Keywords or -KeywordsFile.'};if(-not$OutputPath){$OutputPath=if($Format-eq'Csv'){'.\hwaseong_staff_search_links.csv'}else{'.\hwaseong_staff_search_links.html'}};$rows=$items|ForEach-Object{[pscustomobject]@{Keyword=$_;Url=New-StaffSearchUrl -Keyword $_}};$encoding=New-Object System.Text.UTF8Encoding $true;if($Format-eq'Csv'){$lines=@('keyword,search_link');$lines+=$rows|ForEach-Object{'"{0}","{1}"'-f$_.Keyword.Replace('"','""'),$_.Url.Replace('"','""')};[System.IO.File]::WriteAllText((Resolve-OutputPath -Path $OutputPath),($lines-join[Environment]::NewLine),$encoding)}else{$body=$rows|ForEach-Object{"<tr><td>$([System.Net.WebUtility]::HtmlEncode($_.Keyword))</td><td><a href=\"$([System.Net.WebUtility]::HtmlEncode($_.Url))\">Open search</a></td></tr>"};$html="<!doctype html><html lang=\"ko\"><meta charset=\"utf-8\"><title>Hwaseong Staff Search Links</title><body><table>$($body-join[Environment]::NewLine)</table></body></html>";[System.IO.File]::WriteAllText((Resolve-OutputPath -Path $OutputPath),$html,$encoding)};Write-Output "Created $OutputPath"
